  static _bodyYToNoseY1024(y512) {
    const hN = THREE.MathUtils.clamp(1.0 - (y512 / 512.0), 0.0, 1.0);
    const sy = THREE.MathUtils.clamp((hN - 0.5) * 2.0, -1.0, 1.0);
    const cosT = Math.sign(sy) * Math.pow(Math.abs(sy), 1.0 / 0.76);
    const symV = Math.acos(THREE.MathUtils.clamp(-cosT, -1.0, 1.0)) / Math.PI;
    return (1.0 - symV) * 1024.0;
  }
