  _triggerKacapiSulingPhrase(now) {
    if (!this.initialized || !this.enabled) return;
    const scale = [261.63, 329.63, 349.23, 392.00, 493.88, 523.25, 659.25, 698.46];
    const pattern = [5, 4, 3, 1, 2, 3, 5, 6, 5, 3, 2, 0];
    const idx = pattern[this._kacapiStep % pattern.length];
    const freq = scale[idx];
    const osc = this.ctx.createOscillator();
    osc.type = 'triangle';
    osc.frequency.setValueAtTime(freq, now);
    const flt = this.ctx.createBiquadFilter();
    flt.type = 'lowpass';
    flt.frequency.setValueAtTime(freq * 4.2, now);
    flt.frequency.exponentialRampToValueAtTime(freq * 1.35, now + 0.65);
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.0006, now);
    g.gain.linearRampToValueAtTime(0.016, now + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0005, now + 0.85);
    osc.connect(flt);
    flt.connect(g);
    g.connect(this.masterGain);
    osc.start(now);
    osc.stop(now + 0.88);
    if (this._kacapiStep % 4 === 0) {
      const sulingF = scale[Math.min(scale.length - 1, idx + 2)];
      const sOsc = this.ctx.createOscillator();
      sOsc.type = 'sine';
      sOsc.frequency.setValueAtTime(sulingF * 0.992, now + 0.08);
      sOsc.frequency.linearRampToValueAtTime(sulingF, now + 0.26);
      const vib = this.ctx.createOscillator();
      vib.frequency.value = 5.2;
      const vibG = this.ctx.createGain();
      vibG.gain.value = sulingF * 0.008;
      vib.connect(vibG);
      vibG.connect(sOsc.frequency);
      const sg = this.ctx.createGain();
      sg.gain.setValueAtTime(0.0005, now + 0.08);
      sg.gain.linearRampToValueAtTime(0.010, now + 0.38);
      sg.gain.exponentialRampToValueAtTime(0.0005, now + 1.45);
      sOsc.connect(sg);
      sg.connect(this.masterGain);
      sOsc.start(now + 0.08);
      vib.start(now + 0.08);
      sOsc.stop(now + 1.48);
      vib.stop(now + 1.48);
    }
  }
