  initParticlePools() {
    const sparkGeo = new THREE.BoxGeometry(0.036, 0.036, 0.44);
    sparkGeo.userData.sharedGeo = true;
    this.sparkMatGold = new THREE.MeshBasicMaterial({ color: 0xffb703 });
    this.sparkMatCore = new THREE.MeshBasicMaterial({ color: 0xfef08a });
    this.sparkMatPlasma = new THREE.MeshBasicMaterial({ color: 0x38bdf8 });
    for (let i = 0; i < 96; i++) {
      const baseMat = (i % 5 === 0) ? this.sparkMatCore : this.sparkMatGold;
      const mesh = new THREE.Mesh(sparkGeo, baseMat);
      mesh.visible = false;
      this.particleGroup.add(mesh);
      this.sparkPool.push({
        mesh,
        life: 0,
        maxLife: 0.30,
        floorY: 0.11,
        isCore: (i % 5 === 0),
        vel: new THREE.Vector3()
      });
    }
    const sandGeo = new THREE.BoxGeometry(0.055, 0.045, 0.14);
    sandGeo.userData.sharedGeo = true;
    const sandMat = new THREE.MeshBasicMaterial({ color: 0xfde68a, transparent: true, opacity: 0.72 });
    for (let i = 0; i < 18; i++) {
      const mesh = new THREE.Mesh(sandGeo, sandMat);
      mesh.visible = false;
      this.particleGroup.add(mesh);
      this.sandPool.push({ mesh, life: 0, vel: new THREE.Vector3() });
    }
  }
  applyOriginRebase(deltaX, deltaY = 0, deltaZ = 0) {
    for (const s of this.sparkPool) {
      if (s.life > 0) {
        s.mesh.position.x += deltaX;
        s.mesh.position.y += deltaY;
        s.mesh.position.z += deltaZ;
        s.floorY += deltaY;
      }
    }
    if (this.sandPool) {
      for (const p of this.sandPool) {
        if (p.life > 0) {
          p.mesh.position.x += deltaX;
          p.mesh.position.y += deltaY;
          p.mesh.position.z += deltaZ;
        }
      }
    }
  }
