    const sosOn = this.sosIntercomTimer > 0 ? 1 : 0;
    const key = `${Math.floor(spdDisp / 5)}|${eco}|${fl}|${sosOn}|${this.cabinClass || 'ECONOMY'}|${this.doorsOpen ? 1 : 0}`;
    if (key === this._lastCacpKey) return;
    this._lastCacpKey = key;
    const ctx = this.cacpCtx;
    ctx.fillStyle = '#040b16';
    ctx.fillRect(0, 0, 256, 160);
    ctx.strokeStyle = sosOn ? '#ef4444' : '#0284c7';
    ctx.lineWidth = 3;
