  updateQrTicketTexture() {
    if (!this.qrTicketCtx || !this.qrTicketTex) return;
    const trainNo = this.travelDir >= 0 ? 'G1215' : 'G1218';
    const routeTxt = this.travelDir >= 0 ? 'HALIM ➔ TEGALLUAR' : 'TEGALLUAR ➔ HALIM';
    const clsShort = this.cabinClass === 'FIRST'
      ? 'CAR 01 • SEAT 02A • VIP'
      : (this.cabinClass === 'BUSINESS' ? 'CAR 07 • SEAT 05A • BUSN' : 'CAR 03 • SEAT 08A • ECON');
    const ver = this.qrTicketVerified ? 1 : 0;
    const key = `${trainNo}|${clsShort}|${ver}`;
    if (key === this._lastQrTicketKey) return;
    this._lastQrTicketKey = key;
    const ctx = this.qrTicketCtx;
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, 256, 320);
    ctx.fillStyle = '#dc2626';
    ctx.fillRect(0, 0, 256, 54);
    ctx.fillStyle = '#fbbf24';
    ctx.fillRect(0, 50, 256, 4);
    ctx.fillStyle = '#ffffff';
    ctx.font = '900 17px sans-serif';
    ctx.textAlign = 'left';
    ctx.fillText('WHOOSH', 14, 24);
    ctx.font = 'bold 10px monospace';
    ctx.fillText('KCIC E-BOARDING PASS', 14, 41);
    ctx.textAlign = 'right';
    ctx.font = '900 16px monospace';
    ctx.fillText(trainNo, 242, 32);
    ctx.fillStyle = '#0f172a';
    ctx.font = '900 14px monospace';
    ctx.textAlign = 'center';
    ctx.fillText(routeTxt, 128, 76);
    ctx.fillStyle = '#f1f5f9';
    ctx.fillRect(14, 86, 228, 28);
    ctx.fillStyle = '#b91c1c';
    ctx.font = 'bold 11.5px monospace';
    ctx.fillText(clsShort, 128, 104);
    const qx = 65, qy = 124, cell = 6;
    ctx.fillStyle = '#0f172a';
    const drawFinder = (fx, fy) => {
      ctx.fillRect(qx + fx * cell, qy + fy * cell, 7 * cell, 7 * cell);
      ctx.fillStyle = '#ffffff';
      ctx.fillRect(qx + (fx + 1) * cell, qy + (fy + 1) * cell, 5 * cell, 5 * cell);
      ctx.fillStyle = '#0f172a';
      ctx.fillRect(qx + (fx + 2) * cell, qy + (fy + 2) * cell, 3 * cell, 3 * cell);
    };
    drawFinder(0, 0);
    drawFinder(14, 0);
    drawFinder(0, 14);
    for (let r = 0; r < 21; r++) {
      for (let c = 0; c < 21; c++) {
        const inFinder = (r < 8 && c < 8) || (r < 8 && c > 12) || (r > 12 && c < 8);
        if (inFinder) continue;
        if (((r * 17 + c * 31 + (ver ? 5 : 11)) % 7) < 3) {
          ctx.fillRect(qx + c * cell, qy + r * cell, cell - 0.6, cell - 0.6);
        }
      }
    }
    ctx.fillStyle = ver ? '#065f46' : '#1e293b';
    ctx.fillRect(14, 264, 228, 42);
    ctx.fillStyle = ver ? '#34d399' : '#38bdf8';
    ctx.font = 'bold 11px monospace';
    ctx.textAlign = 'center';
    ctx.fillText(ver ? '✓ TERVERIFIKASI PRAMUGARA' : 'TUNJUKKAN KE PRAMUGARA [[]', 128, 283);
    ctx.fillStyle = '#e2e8f0';
    ctx.font = '9.5px sans-serif';
    ctx.fillText('KCIC Halim • Karawang • Padalarang • Tegalluar', 128, 299);
    this.qrTicketTex.needsUpdate = true;
  }
