  _getSafetyCardMaterial() {
    if (this.safetyCardMat) return this.safetyCardMat;
    if (typeof document === 'undefined') {
      this.safetyCardMat = new THREE.MeshStandardMaterial({ color: 0xf8fafc, roughness: 0.35 });
      return this.safetyCardMat;
    }
    const c = document.createElement('canvas');
    c.width = 256;
    c.height = 340;
    const ctx = c.getContext('2d');
    ctx.fillStyle = '#f8fafc';
    ctx.fillRect(0, 0, 256, 340);
    ctx.fillStyle = '#dc2626';
    ctx.fillRect(0, 0, 256, 56);
    ctx.fillStyle = '#fbbf24';
    ctx.fillRect(0, 52, 256, 5);
    ctx.fillStyle = '#ffffff';
    ctx.font = '900 16px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('WHOOSH KCIC400AF', 128, 24);
    ctx.font = 'bold 11px sans-serif';
    ctx.fillText('PETUNJUK KESELAMATAN / SAFETY', 128, 43);
    const boxes = [
      { x: 14, y: 70, col: '#0284c7', title: '1. PALU DARURAT', sub: 'Pukul sudut merah kaca', icon: 'HAMMER' },
      { x: 134, y: 70, col: '#059669', title: '2. PINTU DARURAT', sub: 'Ikuti jalur evakuasi hijau', icon: 'EXIT' },
      { x: 14, y: 186, col: '#d97706', title: '3. INTERKOM SOS', sub: 'Tekan tombol PEC bordes', icon: 'SOS' },
      { x: 134, y: 186, col: '#dc2626', title: '4. BEBAS ROKOK', sub: 'Dilarang merokok & vape', icon: 'NOSMOKE' }
    ];
    for (let i = 0; i < boxes.length; i++) {
      const b = boxes[i];
      ctx.strokeStyle = '#cbd5e1';
      ctx.lineWidth = 2;
      ctx.strokeRect(b.x, b.y, 108, 104);
      ctx.fillStyle = b.col;
      ctx.fillRect(b.x, b.y, 108, 22);
      ctx.fillStyle = '#ffffff';
      ctx.font = 'bold 10px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(b.title, b.x + 54, b.y + 15);
      const cx = b.x + 54, cy = b.y + 56;
      ctx.strokeStyle = b.col;
      ctx.fillStyle = b.col;
      ctx.lineWidth = 3;
      if (b.icon === 'HAMMER') {
        ctx.fillRect(cx - 14, cy - 12, 28, 8);
        ctx.fillRect(cx - 3, cy - 4, 6, 22);
      } else if (b.icon === 'EXIT') {
        ctx.strokeRect(cx - 14, cy - 14, 28, 28);
        ctx.fillRect(cx - 4, cy - 6, 12, 16);
      } else if (b.icon === 'SOS') {
        ctx.beginPath();
        ctx.arc(cx, cy, 13, 0, Math.PI * 2);
        ctx.stroke();
        ctx.font = 'bold 10px monospace';
        ctx.fillText('SOS', cx, cy + 4);
      } else {
        ctx.beginPath();
        ctx.arc(cx, cy, 14, 0, Math.PI * 2);
        ctx.stroke();
        ctx.beginPath();
        ctx.moveTo(cx - 10, cy - 10);
        ctx.lineTo(cx + 10, cy + 10);
        ctx.stroke();
      }
      ctx.fillStyle = '#334155';
      ctx.font = 'bold 8.5px sans-serif';
      ctx.fillText(b.sub, cx, b.y + 94);
    }
    ctx.fillStyle = '#0f172a';
    ctx.fillRect(0, 306, 256, 34);
    ctx.fillStyle = '#38bdf8';
    ctx.font = 'bold 10px monospace';
    ctx.textAlign = 'center';
    ctx.fillText('KCIC HALIM–PADALARANG–TEGALLUAR', 128, 321);
    ctx.fillStyle = '#e2e8f0';
    ctx.font = '9px sans-serif';
    ctx.fillText('Simpan kembali di kantong kursi [.]', 128, 334);
    const tex = new THREE.CanvasTexture(c);
    tex.colorSpace = THREE.SRGBColorSpace;
    this.safetyCardMat = new THREE.MeshStandardMaterial({ map: tex, roughness: 0.32, metalness: 0.05 });
    return this.safetyCardMat;
  }
