  _getSeatRowPlaqueMat(cabinClass = 'ECONOMY', side = -1, rowNum = 1) {
    const key = `${cabinClass}|${side}|${rowNum}`;
    if (this.seatRowPlaqueCache.has(key)) return this.seatRowPlaqueCache.get(key);
    if (typeof document === 'undefined') {
      const fb = new THREE.MeshBasicMaterial({ color: 0x0f172a });
      this.seatRowPlaqueCache.set(key, fb);
      return fb;
    }
    const c = document.createElement('canvas');
    c.width = 160;
    c.height = 64;
    const ctx = c.getContext('2d');
    ctx.fillStyle = '#090d16';
    ctx.fillRect(0, 0, 160, 64);
    ctx.strokeStyle = '#334155';
    ctx.lineWidth = 3;
    ctx.strokeRect(2, 2, 156, 60);
    ctx.fillStyle = cabinClass === 'FIRST' ? '#b45309' : (cabinClass === 'BUSINESS' ? '#b91c1c' : '#0369a1');
    ctx.fillRect(6, 6, 44, 52);
    ctx.fillStyle = '#ffffff';
    ctx.font = '900 22px monospace';
    ctx.textAlign = 'center';
    ctx.fillText(String(rowNum).padStart(2, '0'), 28, 40);
    let letters = ['A', 'C'];
    if (cabinClass === 'ECONOMY') {
      letters = side < 0 ? ['D', 'F'] : ['A', 'B', 'C'];
    } else if (cabinClass === 'BUSINESS') {
      letters = side < 0 ? ['A', 'C'] : ['D', 'F'];
    } else {
      letters = side < 0 ? ['A'] : ['D', 'F'];
    }
    const spanW = 98;
    for (let i = 0; i < letters.length; i++) {
      const lx = 56 + ((i + 0.5) / letters.length) * spanW;
      ctx.fillStyle = '#f8fafc';
      ctx.font = 'bold 17px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(letters[i], lx, 28);
      const stHash = (rowNum * 7 + i * 3 + (side > 0 ? 2 : 1)) % 4;
      const ledHex = stHash === 0 ? '#22c55e' : (stHash === 1 ? '#facc15' : '#ef4444');
      ctx.fillStyle = ledHex;
      ctx.fillRect(lx - 10, 36, 20, 7);
      ctx.fillStyle = '#cbd5e1';
      ctx.font = 'bold 8px monospace';
      ctx.fillText(stHash === 0 ? 'VCN' : (stHash === 1 ? 'RSV' : 'OCC'), lx, 55);
    }
    const tex = new THREE.CanvasTexture(c);
    tex.colorSpace = THREE.SRGBColorSpace;
    const mat = new THREE.MeshBasicMaterial({ map: tex });
    this.seatRowPlaqueCache.set(key, mat);
    return mat;
  }
