  updateCoachPIDTexture(speedKmh = 0, nextStationShort = 'PADALARANG', clockHm = '07:30', customTicker = '') {
    if (!this.coachPidNeedsDraw && this.interiorCoachGroup && !this.interiorCoachGroup.visible) {
      return;
    }
    this.coachPidNeedsDraw = false;
    const dispSpeed = Math.round(Number(speedKmh) || 0);
    const ctx = this.coachPidCtx;
    ctx.fillStyle = '#05070d';
    ctx.fillRect(0, 0, 512, 128);
    ctx.strokeStyle = '#1e293b';
    ctx.lineWidth = 3;
    ctx.strokeRect(3, 3, 506, 122);
    const carLabel = this.cabinClass === 'FIRST'
      ? 'CAR 01 • FIRST (A | D-F)'
      : (this.cabinClass === 'BUSINESS' ? 'CAR 07 • BUSN (A-C | D-F)' : 'CAR 03 • ECON (A-B-C | D-F)');
    ctx.fillStyle = '#f59e0b';
    ctx.font = 'bold 16px JetBrains Mono, monospace';
    ctx.textAlign = 'left';
    ctx.fillText(carLabel, 14, 28);
    ctx.fillStyle = '#ef4444';
    ctx.font = '900 32px JetBrains Mono, monospace';
    ctx.textAlign = 'right';
    ctx.fillText(`${dispSpeed} KM/H`, 496, 34);
    ctx.fillStyle = '#1e293b';
    ctx.fillRect(14, 44, 484, 2);
    ctx.fillStyle = '#fbbf24';
    ctx.font = 'bold 18px JetBrains Mono, monospace';
    ctx.textAlign = 'left';
    ctx.fillText(`BERIKUT: ${String(nextStationShort || 'PADALARANG').toUpperCase()}`, 14, 70);
    ctx.fillStyle = '#34d399';
    ctx.textAlign = 'right';
    ctx.fillText(`23°C • ${clockHm} WIB`, 496, 70);
    ctx.fillStyle = '#0f172a';
    ctx.fillRect(12, 82, 488, 34);
    const tickerBase = customTicker ||
      'SELAMAT DATANG DI KERETA CEPAT WHOOSH • SENANG DAPAT MENJADI BAGIAN DARI PERJALANAN ANDA • WAKTU HEMAT, OPERASI OPTIMAL, SISTEM HEBAT — WHOOSH, WHOOSH, WHOOSH, YES! • ';
    const fullTicker = tickerBase + tickerBase;
    this.coachPidScrollPx = ((this.coachPidScrollPx || 0) + 18) % Math.max(240, tickerBase.length * 9.6);
    ctx.save();
    ctx.beginPath();
    ctx.rect(14, 82, 484, 34);
    ctx.clip();
    ctx.fillStyle = '#38bdf8';
    ctx.font = 'bold 15px JetBrains Mono, monospace';
    ctx.textAlign = 'left';
    ctx.fillText(fullTicker, 16 - this.coachPidScrollPx, 104);
    ctx.restore();
    this.coachPidTexture.needsUpdate = true;
  }
