        _right.set(sideSgn, 0, 0).transformDirection(bogiePick.matrixWorld).normalize();
        const relBackSpd = 6.5 + Math.random() * 9.5 + absSpd * 0.18;
        const outSpray = (0.6 + Math.random() * 2.8) * (0.6 + sparkIntensity * 0.6);
        const upKick = 1.1 + Math.random() * 3.4 * (0.7 + sparkIntensity * 0.5);
