      if (forceNewSpot || this.mbzCarS < 10400 || this.mbzCarS > 46900) {
        this._mbzSpotIdx = ((this._mbzSpotIdx || 0) + 1) % hotspots.length;
        this.mbzCarS = hotspots[this._mbzSpotIdx];
      }
