        const aiDir = -tDir;
        const aiOffset = (carDir === aiDir) ? -22.0 : 215.0;
        this.train.aiTrainS = THREE.MathUtils.clamp(this.mbzCarS + carDir * aiOffset, 10100.0, 47300.0);
